head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#07111d" value="#07111d"/><Variable name="page.text" description="Text color" type="color" default="#d5e4ef" value="#d5e4ef"/><Variable name="theme.accent" description="Accent color" type="color" default="#aaff64" value="#aaff64"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Chakra Petch', Courier New, monospace;--body:Courier New, monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{background:#07111d;color:#d5e4ef;font-family:"Courier New",monospace;margin:0}.save-nav{max-width:1180px;margin:auto;padding:28px 30px;display:flex;justify-content:space-between;border-bottom:1px solid #314259}.save-nav .brand{color:#aaff64;font-weight:bold;letter-spacing:1px;text-decoration:none}.save-nav nav{display:flex;gap:28px;font-size:11px}.save-nav nav a{text-decoration:none}.save-start{max-width:1180px;margin:auto;padding:64px 30px;display:grid;grid-template-columns:1.2fr 1fr;gap:55px;align-items:center}.save-screen{border:7px solid #2c3e52;box-shadow:0 0 0 2px #53687f,10px 10px 0 #000;background:#101b2c;position:relative}.save-screen::after{content:"";position:absolute;inset:32px 0;pointer-events:none;background:repeating-linear-gradient(transparent 0 3px,#0002 3px 4px)}.save-status,.save-screen-footer{display:flex;justify-content:space-between;padding:13px;font-size:9px;color:#aaff64;background:#142338}.save-screen-footer{color:#9eafc0;font-size:8px}.save-level{color:#ffcc66;font-size:10px;letter-spacing:1px}.save-start h1{font-size:clamp(30px,3.4vw,49px);line-height:1.1;letter-spacing:-2px;margin:24px 0}.save-start p{font-size:13px;line-height:1.85;color:#a9bacd}.save-button{display:inline-block;background:#aaff64;color:#07111d;padding:17px;margin-top:20px;box-shadow:5px 5px 0 #3d6e3d;text-decoration:none;font-size:11px;font-weight:bold;transition:transform .15s}.save-button:hover{transform:translate(2px,2px)}.save-stats{display:flex;gap:35px;margin-top:36px}.save-stats strong{display:block;color:#ffcc66;font-size:20px}.save-stats span{font-size:8px;color:#a9bacd;display:block;margin-top:8px}.save-quests{max-width:1120px;margin:0 auto 30px;border:1px solid #314259;background:#0c1928;padding:24px}.save-section-label{display:flex;justify-content:space-between;color:#aaff64;font-size:10px;letter-spacing:1px;padding-bottom:20px}.save-cartridge{display:grid;grid-template-columns:70px 1fr 30px;align-items:center;gap:24px;padding:25px 18px;border-top:1px solid #314259;text-decoration:none;transition:background .2s}.save-cartridge:hover{background:#182e40}.save-cartridge>b{color:#415b70;font-size:40px}.save-cartridge small{color:#ffcc66;font-size:9px}.save-cartridge h2{font-size:22px;margin:8px 0}.save-cartridge p{color:#a9bacd;font-size:11px;margin:0}.save-cartridge>span{color:#aaff64;font-size:28px}.section-heading{max-width:1120px;margin:58px auto 24px;font-size:15px;color:#aaff64;letter-spacing:2px}.posts-grid{max-width:1120px;margin:0 auto 60px;display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.post-card{border:1px solid #314259;background:#0c1928;padding:18px}.post-media{aspect-ratio:1.6;background:#203a48;image-rendering:pixelated;margin-bottom:20px}.post-meta{color:#ffcc66;font-size:9px}.post-title{font-size:19px;line-height:1.35}.post-excerpt{color:#a9bacd;font-size:11px}.save-tip{text-align:center;margin:0 auto 60px;max-width:1120px;padding:45px 20px;border:1px dashed #aaff64;background:#102128}.save-tip>span{color:#aaff64;font-size:10px;letter-spacing:2px}.save-tip h2{font-size:25px}.save-tip p{font-size:12px;line-height:1.8;color:#a9bacd}.save-tip a{display:inline-block;font-size:10px;color:#aaff64;margin-top:18px}.save-footer{max-width:1180px;margin:auto;padding:30px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px;border-top:1px solid #314259;font-size:11px;color:#aaff64}.save-footer small{flex-basis:100%;color:#8395a8;font-size:9px}@media(max-width:700px){.save-nav{padding:22px 18px}.save-nav nav{gap:10px;font-size:8px}.save-start{grid-template-columns:1fr;padding:35px 22px;gap:40px}.save-quests,.save-tip{margin:20px}.save-cartridge{grid-template-columns:40px 1fr 20px;padding:22px 0;gap:12px}.save-cartridge h2{font-size:18px}.posts-grid{grid-template-columns:1fr;margin:20px}.section-heading{margin:40px 20px 20px}.save-tip h2{font-size:20px}} .latest{max-width:none;margin:0;padding:0}
h1,h2,h3{font-family:'Chakra Petch', Courier New, monospace}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
